def refs(ids): return ' '.join(f'<a class="ref" href="#s{x}">[{x}]</a>' for x in ids.split(','))
def table(head,rows): return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def graph(name,body):
 dot='digraph G { graph [rankdir=TB,bgcolor="transparent",pad="0.25",nodesep="0.35",ranksep="0.45"]; node [shape=box,style="rounded,filled",fillcolor="#eef5f6",color="#91a6af",fontname="Arial",fontsize=14,margin="0.16,0.12"]; edge [color="#627987",fontname="Arial",fontsize=11,arrowsize=0.7];'+body+'}'
 svg=subprocess.check_output(['dot','-Tsvg'],input=dot.encode()).decode(); svg=svg[svg.index('<svg'):]; svg=re.sub(r'<svg width="[^"]+" height="[^"]+"','<svg role="img" aria-label="'+name+'"',svg, count=1)
 return '<div class="graph">'+svg+'</div>'
