parts=[]
def section(i,title,body):parts.append(f'<section id="{i}"><h2>{title}</h2>{body}</section>')
section('read','01 · Read the system correctly', '''<p class="lead">The useful unit of approval is <strong>a specific scope of work, on a specific design revision, released for a specific milestone</strong>. A project can be ready for structural review while blocked from clearing; it can have a building permit and still lack authority to install a septic system or work in water.</p><p>This report maps ordinary residential development, additions/ADUs, subdivisions and common commercial site work in Kitsap County. It adds conditional state, federal, tribal and utility branches. It is a research-backed workflow specification, not a parcel-specific approval or a complete rule engine for every industrial, federal or tribal project. <strong>Sources checked November 5, 2026.</strong> Local numerical thresholds, vesting and individual permit conditions must be attached to the actual project.</p><p><strong>Evidence labels:</strong> “Documented” means the cited authority describes the requirement. “Model” means a proposed Davapprove coordination rule. “Confirm” means the responsible agency must resolve applicability or procedure. The diagrams are model views of documented relationships; they do not assert that every displayed branch applies to every parcel.</p>'''+overview+'''<p><strong>Edges have different meanings.</strong> A report can be needed to start review; a decision can be needed to issue another permit; an issued permit can remain ineffective until a waiting period ends. These must not be represented by one undifferentiated “depends on” edge.</p>'''+table(['Edge','What it means','Example'],[
('INPUT','Evidence needed for a determination or design','Wetland boundary → septic/civil layout'),('HARD','Legal or procedural prerequisite at the named milestone','401 certification/waiver → applicable federal issuance'),('CONSULT','A responsible agency must finish consultation; applicant does not issue the decision','Federal agency → tribal / ESA consultation'),('CONDITION','Approval exists but obligations remain','Preconstruction meeting, mitigation security, work window'),('RIGHT','Property permission independent of regulatory approval','DNR lease / recorded drainage easement'),('INVALIDATES','Change requires impact review; it does not automatically revoke a legal permit','Moved footprint → stale civil, septic and shoreline evidence'),('RECOMMENDED','Internal risk-reduction gate','All disciplines accept common plan before detailed design')]))
section('jurisdiction','02 · Jurisdiction is a router, not a county-wide default',table(['Place or asset','Decision authority / routing','What remains separate'],[
('Unincorporated private land','Kitsap DCD for building, planning, environmental and development-engineering functions; Public Works for county ROW; fire code review. '+refs('01,09,57'),'KPHD, utilities and triggered state/federal approvals.'),
('Bainbridge Island','City Planning & Community Development and Public Works; city zoning, shoreline, critical-area and engineering rules. '+refs('41'),'KPHD for septic/well path; water/sewer purveyor; L&I electrical. County parcel records are not county permitting jurisdiction.'),
('Bremerton','City DCD and relevant review departments. Its published process describes departmental re-review on revisions. '+refs('42'),'Separate utility/ROW and fire functions; do not assume only the changed discipline will re-review.'),
('Poulsbo','City Building, Planning and Engineering. Engineering reviews infrastructure, drainage and ROW. '+refs('43,44'),'Utility capacity, fees and conditions are their own gates; KPHD where relevant.'),
('Port Orchard','Permit Center routes to Planning, Building, Fire, Addressing, Engineering and Public Works. '+refs('45,59'),'Use city land-disturbance and ROW processes, not county SDAP thresholds.'),
('Reservation / trust / restricted land','Determine land tenure and governing authority first. Suquamish’s FAQ routes individually owned Port Madison property to county permitting and identifies federal land-use requirements for trust property. '+refs('39'),'Do not infer exclusive tribal or county authority from reservation boundaries alone. Confirm trust-land construction, environmental and lease approvals with the tribe/BIA as applicable.'),
('Tribal environmental interests off reservation','Affected tribes can participate through treaty, cultural-resource, SEPA and federal consultation processes. Port Gamble S’Klallam maintains an environmental permit-review program. '+refs('32,40'),'No generic “tribal approval” checkbox for all private parcels. Record each tribe’s role and legal basis; Suquamish and Port Gamble S’Klallam are not necessarily the only affected tribes.'),
('State highway / public road / aquatic bedlands','Identify asset owner and access-control class, including off-site work. City limits can change highway-access routing. '+refs('35,46,47'),'Permit authority, property owner, utility operator and maintenance acceptor can be different parties.'),
('Federal property, installation or funding','Create a separate federal-land/funding jurisdiction branch; identify federal lead and contractual permissions.','This report screens the branch; it does not specify Navy-base construction, security or federal facility approval processes.')])+'''<p><strong>Required parcel inputs:</strong> legal description and parcel history; city boundary; ownership/tenure; zoning and overlays; legal access; proposed use and unit/bedroom count; project and off-site disturbance footprints; water/sewer service area; shoreline/critical-area indicators; prior permits, conditions, easements, notices to title and forest-conversion history. A tax parcel is not proof of a legal buildable lot. '''+refs('02')+'''</p>''')
section('design','03 · Resolve the septic–civil–wetland–shoreline–designer loop',loop+'''<p>The coordination gate below is a <strong>recommended product workflow</strong>, not a new government approval. It is the main opportunity to prevent avoidable redesign.</p>'''+table(['Shared variable','Affected disciplines','What to settle before freezing a layout'],[
('Wetland edge, rating, stream location and applicable buffers','Biologist, surveyor, septic designer, civil, architect, planner','Field evidence, reviewer acceptance and where survey is needed. County wetland code explicitly carries wetland/buffer geometry into septic, utility, grading and other plans. '+refs('04')),
('Primary and reserve septic areas; bedroom/flow capacity','Septic, designer, civil, landscape, owner','Reserve area is an occupied design constraint, not spare land for stormwater or future additions. Resolve existing-system clearance versus BSA route. '+refs('12,13')),
('Grades, groundwater and infiltration','Geotechnical, septic, civil, structural','Different soil investigations answer different questions. Reuse observations where appropriate, but do not treat a septic test pit as automatic stormwater infiltration or foundation certification.'),
('House footprint, height, floors and retaining walls','Designer, structural, civil, shoreline, septic','Compare footprint alternatives against all constraints before detailed structural work. Smaller footprint can increase height or retaining needs.'),
('Driveway, turning area, hydrants and fire flow','Civil, fire reviewer, water utility, biologist','Potable availability is not proof of fire flow. A longer drive increases impervious area and may create wetland crossings. '+refs('08,10')),
('Outfall and off-site drainage route','Civil, geotechnical, adjacent owner, WDFW, Ecology, Corps','Confirm lawful discharge rights and whether work in water activates permits; infiltration infeasibility may create a wholly new aquatic branch. '+refs('30,27,35')),
('Construction staging and temporary disturbance','All site disciplines and contractor','Excavation access, stockpiles, erosion controls and utility trenches must fit too. Do not show only permanent improvements.')])+'''<ol><li><strong>Build the common base:</strong> obtain records, identify contradictions and survey uncertainty, flag critical features.</li><li><strong>Run feasibility studies in parallel:</strong> septic soils/reserve, ecology, geotechnical/drainage, water and access. Share proposed investigation locations before disturbing sensitive ground.</li><li><strong>Compare feasible layouts:</strong> keep alternative house, wastewater and discharge strategies explicit. Identify potentially fatal constraints before polishing architecture.</li><li><strong>Resolve interfaces:</strong> every discipline accepts the same geometry revision and a list of remaining assumptions. Ask agencies focused questions that affect layout.</li><li><strong>Release detailed design:</strong> proceed only after high-cost uncertainties are resolved or explicitly accepted by the owner.</li><li><strong>Submit coordinated packages:</strong> applications may run in parallel where allowed. Each package identifies the exact common revision.</li></ol><p>Model the envelope as <strong>scenario-dependent feasible geometry</strong>, not merely parcel minus buffers. Access, wastewater, drainage, constructability and service rights must all fit. Buffer reductions and variances are alternate unapproved scenarios until granted; they must not enlarge the approved envelope in advance.</p>''')
section('nodes','04 · Approval and evidence node register', '<p>Each row is a node template. “Blocks” identifies the relevant milestone rather than imposing a universal ordering of application submissions. A project instantiates only the applicable nodes; uncertainty stays visible. Required professional qualifications are detailed in section 08.</p>'+table(['ID / node','Responsible party / activation','Required result / blocking effect','Professional / sources'],[(f'<b>{x["id"]} · {x["title"]}</b>',x['authority']+'<br><span class="muted">'+x['trigger']+'</span>',x['evidence']+'<br><b>Blocks:</b> '+x['blocks'],x['professional']+'<br>'+refs(','.join(x['sources']))) for x in N]))
section('external','05 · External approvals are overlapping, conditional gates',aquatic+'''<p><strong>JARPA standardizes an application, not an approval.</strong> It can support multiple aquatic permits, but every authority retains its decision and may require separate submissions and supporting information. '''+refs('36')+'''</p>'''+table(['Branch','Logic and workflow consequence'],[
('Local critical areas + shoreline','Both can constrain the site. Shoreline substantial-development exemption does not eliminate substantive shoreline requirements or a needed CUP/variance. Local approval of a shoreline CUP/variance also needs Ecology approval. '+refs('25')),
('Shoreline effective date','Track filing separately from local decision. WAC 173-27-190 restricts construction for 21 days from the defined filing date, or until timely review proceedings terminate, subject to statutory exceptions. Do not start this clock from application submission. '+refs('26')),
('Federal waters','Section 404 concerns discharge of dredged/fill material into WOTUS; Section 10 concerns work/structures in navigable waters. Wetland presence alone is not a universal Corps-permit trigger. Record the Corps route, relevant conditions and PCN requirements. '+refs('27,52')),
('Federal versus state wetland scope','A negative federal jurisdiction result does not clear the wetland for development. Ecology describes administrative orders for impacts to non-federally regulated wetlands; local critical-area requirements remain. '+refs('29')),
('401 and coastal consistency','Where required, federal issuance depends on certification/waiver and applicable coastal-consistency compliance. Determine the competent certifying authority and whether general coverage applies; do not assume Ecology is always the certifier. '+refs('28,52')),
('ESA / EFH','The federal agency makes effect findings and obtains required consultation with NMFS/USFWS. A consultant’s biological report is evidence, not consultation completion. Conditions can alter methods, timing and footprint. '+refs('31,52')),
('Section 106 + treaty rights','Historic-property consultation and treaty-rights consultation are distinct. A completed archaeological report does not alone complete either process. The Corps generally completes necessary tribal coordination before deciding the permit. '+refs('32,33')),
('HPA','WDFW hydraulic jurisdiction is a separate activity test and can reach work above ordinary high water. Carry the authorized methods and work windows into the construction schedule. '+refs('30')),
('Aquatic ownership','DNR authorization is a property contract, separate from regulatory permits. Other bedland owners may hold the relevant rights. Early ownership checks avoid designing a facility where the necessary use is unavailable. '+refs('35')),
('Construction stormwater','Evaluate disturbance, common-plan acreage, off-site support areas and potential surface-water discharge. Ecology’s current permit is effective 2026–2030. Smaller sites can still be designated based on pollution risk. Indian Country routing can involve EPA. '+refs('37,38')),
('SEPA and NEPA','SEPA is a review process led by the designated agency, usually local government for private development. Federal action may add NEPA; one does not automatically replace the other. Coordinated documents are possible. Exemption is determined for the whole proposal. '+refs('23,24')),
('Archaeology without federal permit','State archaeological protection can apply independently of Section 106. An alteration permit may be needed on private property too; discovery during construction creates a separate affected-work hold and response process. '+refs('34'))]))
section('edges','06 · Gate expressions and an explicit edge register', '''<p>These are <strong>model expressions</strong>. Attach the jurisdiction-specific prerequisite and actual permit conditions before using them to authorize a real stage. An AND gate evaluates only required inputs; an OR gate requires an approved, applicable alternative—not merely an available idea.</p><pre>Wastewater_ready = approved_sewer_route
                OR approved_new_OSS_design
                OR accepted_existing_OSS_clearance
                OR approved_applicable_large_system_route

Building_issue = local_required_reviews_pass
             AND water_and_wastewater_evidence_accepted
             AND required_entitlements_effective
             AND issuance_conditions_and_fees_satisfied

Start(work_package) = every_authorization_for_that_work_effective
                  AND prestart_conditions_met
                  AND property_rights_secured
                  AND current_design_matches_authorizations
                  AND no_applicable_hold_or_expiration
                  AND permitted_work_window_open

Occupy = occupancy_authority_release
      AND all_required_final_releases_or_express_deferrals
      AND life_safety_and_utility_conditions_satisfied</pre>'''+table(['From → to','Type / stage','Meaning / basis'],[
('J0 → every authority-owned node','INPUT / routing','Confirm territorial and subject-matter authority before applying rules.'),
('L0, B0, E0, G0, W0, S0, A0 → D0','INPUT / internal design release','Sufficient evidence for a coordinated layout; some studies can proceed with documented assumptions.'),
('S0 → S1 OR S2 OR S3 OR LOSS route','OR / wastewater branch','Use applicable authorized route; do not assume sewer and septic are freely interchangeable. '+refs('12,13,48')),
('S2 → B2 → S4','HARD / relevant approvals','New OSS design precedes building; installation is later. Ordinance allows a joint health/building waiver of the ordinary building prerequisite. '+refs('11,12')),
('E0 → E1; E0 → C0, S2, D0','INPUT / environmental and design','Accepted wetland geometry must be represented consistently. '+refs('04')),
('G0 → C0, B1','INPUT / technical acceptance','Slope, bearing, infiltration and discharge assumptions affect civil and building designs. '+refs('03,05')),
('Q0 → nonexempt local decisions; Q0 → T0','HARD / decision or coverage','SEPA prerequisites vary by action. Ecology’s NOI specifically requires applicable SEPA completion. '+refs('23,54')),
('H0 → H1 → H2','HARD / CUP or variance release','Ecology review only on applicable path; SDP follows filing/waiting route without CUP/variance approval. '+refs('25,26')),
('U1, U2, U3, U4, U5 → U6','HARD or CONSULT / federal decision','Only applicable federal requirements; not every project requires each consultation.'),
('U6 or U7, U8, U9, H2 → aquatic Start','HARD + RIGHT + CONDITION','Select federal/state branch; require all other applicable aquatic permissions. '+refs('27,29,30,35')),
('C0, A0, E1, F0 → V0 or B1','HARD / applicable technical approval','Exact local application matrix and conditions determine which are necessary. '+refs('06,07,10,22')),
('Local development approval → R0 (WSDOT)','HARD / connection issuance','Written development approval ordinarily precedes permit; letter of intent can support local decision. Split preliminary and final states to avoid a false cycle. '+refs('47')),
('T0, R0, V0 + triggered external permissions → site Start','HARD / affected work package','A building permit alone does not authorize every off-site or environmental activity.'),
('B1 + issuance obligations → B2','AND / building issuance','All applicable departmental approvals and issuance requirements. '+refs('01,45')),
('S4, X0, I0 → applicable final releases → O0','HARD / construction and occupancy','Inspection and service completion are separate from plan approval. '+refs('01,12,49')),
('Z0 final recording → new-lot building route','HARD / new legal lots','Confirm any permitted concurrent processing; do not treat preliminary plat approval as recorded legal lots. '+refs('02')),
('Z1 moratorium → P0 / Z0 / B2','HOLD / affected approval','Applicable forest-conversion restrictions can block otherwise compliant development. '+refs('50')),
('Changed inputs → affected nodes','INVALIDATES / impact review','Mark the evidence stale; obtain determination whether amendment/review is necessary. Preserve legal approval history.')])+'''<p><strong>Keep construction releases granular:</strong> investigation, clearing, grading, ROW work, aquatic work, foundations, septic installation, trade work and occupancy can each have different prerequisites. A lawful limited release must not be expanded to other scopes by the software.</p>''')
section('states','07 · State, blockage, revisions and appeals',state+table(['State / dimension','Software behavior'],[
('Applicability: unknown / required / not applicable','Unknown never counts as passed. N/A requires a dated reason, scope and competent determination—not a user deleting an inconvenient node.'),
('Evidence: missing / draft / submitted / accepted / superseded','Evidence acceptance is separate from permit decision. A stamped report can still be rejected or require changes.'),
('Decision: reviewing / RFI / approved / conditional / denied','RFI blocks the relevant decision, not necessarily unrelated design. Denial requires redesign, lawful alternative or appeal; mere passage of time does not clear it.'),
('Effectiveness: waiting / effective / stayed / expired','An approved decision may not yet authorize work. Do not assume every appeal automatically stays every permit; track the governing rule/order.'),
('Conditions: pre-issuance / prestart / inspection / occupancy / ongoing','Only conditions due for this stage block this stage. A five-year monitoring requirement need not block occupancy if the permit allows that sequencing.'),
('Freshness: current / suspect / revalidation required','A changed plan triggers impact review, not automatic legal revocation. Preserve issued status while withholding internal reliance until relevance is confirmed.'),
('Agency clocks and seasonal clocks','Store complete-application date, information requests, response dates, decision, filing, appeal deadlines, expiration and seasonal field/work windows separately. Never promise a completion date from a generic published turnaround.')])+'''<h3>Revision propagation examples</h3>'''+table(['Change','Recheck first','Then test downstream impact'],[
('Three bedrooms become four','OSS capacity, water demand, floor-plan classification','BSA, house layout, reserve area, environmental/civil plan references and building conditions.'),
('Wetland boundary moves inward','Buffer and development overlap','Septic primary/reserve, grading, driveway, footprint, mitigation and each agency’s approved impact area.'),
('Civil design abandons infiltration','Geotechnical limitation and proposed outfall','Drainage easement, downstream capacity, HPA, Corps, shoreline, wetland and water-quality route.'),
('Fire reviewer requires larger turnaround','Access geometry and emergency service assumptions','Added impervious area, stormwater sizing, buffer/OSS conflict, grading and retaining walls.'),
('Shoreline decision moves house inland','House footprint and setbacks','Septic reserve, foundation/geotechnical scope, drainage and construction access.'),
('Survey corrects a boundary or easement','Legal buildable area and rights','All geometry tied to the old survey; no arbitrary age-based assumption that the old drawing is valid.'),
('Excavation reveals archaeology or unexpected soils','Affected-work hold and agency/professional response','Redesign, investigation scope, permit amendments and work-package release. Unaffected work proceeds only if expressly lawful.'),
('Material change after SEPA review','Lead-agency determination of adequacy','Possible addendum, supplemental review or new determination; SEPA documents have no single universal age-expiration rule. '+refs('53'))])+'''<p><strong>RFI workflow:</strong> capture the comment verbatim with source page, affected node, agency, requested evidence and response owner. Classify it as missing information, code conflict, discretion, inter-plan conflict or new scope. Prepare one revision manifest, identify every changed variable, obtain discipline signoff and submit to each affected agency. If agencies conflict, request a documented joint resolution; do not quietly satisfy one by violating another.</p><p><strong>Appeals:</strong> create an appeal child node with forum, filing deadline, standing, record, scope, stay status and outcome. Shoreline, local land-use, health, federal and other state decisions do not share one appeal process. The operative notice and governing law determine deadlines. A pending appeal can be a legal hold, a financial risk, or both; represent them separately.</p>''')
section('professionals','08 · Required professional, recommended professional, or owner work?', '''<p class="lead">An owner can prepare many applications and some building plans. That does not create a general right to self-certify regulated engineering, surveying or septic design.</p><h3>Can an owner design a septic system?</h3><p><strong>For the ordinary Kitsap path, use a licensed OSS designer or qualified professional engineer.</strong> KPHD Ordinance 2025-01 §6.K requires licensed design. State WAC 246-272A-0230 allows a local health officer, at discretion, to let a resident owner design a single-family system outside 200 feet of a marine shoreline; that is not an automatic owner entitlement. No routine Kitsap owner-design pathway was established by the reviewed local materials. Treat any claimed exception as requiring a specific written health-officer determination before relying on it. '''+refs('11,15')+'''</p><p><strong>Owner installation is a different question.</strong> KPHD §12.B provides a limited resident-owner installation route with system, location, competency and designer-oversight conditions. It does not waive licensed design. '''+refs('11')+'''</p><h3>Can an owner do structural calculations?</h3><p><strong>Owner-prepared prescriptive residential plans can be possible; owner calculations do not substitute for a required professional seal.</strong> RCW 18.08.410 exempts specified residential design—including up to four dwelling units—from architect licensure. It is an architectural exemption, not blanket authorization to practice engineering. RCW 18.43.130 contains no general homeowner engineering exemption. Select the actual code path and obtain the building official’s requirements for any engineered portions. '''+refs('16,17,18')+'''</p><p>The practical distinction is selecting code-permitted members and details within all prescriptive limits versus performing a project-specific engineered design. A building can combine both. Bremerton’s linked engineering handout explains that distinction, but it is dated 2007: <strong>its numerical criteria and submission instructions must not be used as current code.</strong> '''+refs('20')+'''</p>'''+table(['Work product','Required / conditional / recommended','Owner role'],[
('Architectural layout and application plans','Architect not universally required for the statutory exempt categories; design professional required when applicable law/code demands it. '+refs('16,19'),'Owner may prepare exempt plans. Complex coordination still benefits from a designer.'),
('Engineered structural components','Appropriately licensed design professional for required engineered work. Confirm competence and any SE requirements for significant structures. '+refs('17,18'),'Owner may develop a concept; cannot create or replace a required seal. Not every house requires an SE specifically.'),
('Changes to sealed plans','Approval by original professional or another qualified professional taking responsibility. '+refs('19'),'Do not edit a professional’s sealed plan and continue presenting it as their work.'),
('Septic design / BSA','Licensed OSS designer or qualified PE on ordinary Kitsap route. '+refs('11,12'),'Provide project needs and records; cannot bypass design qualifications by meeting dimensions alone.'),
('Existing-system clearance','Owner application possible; system/capacity issues can send it back to licensed design. '+refs('13'),'Prepare accurate site plan and records; protect reserve.'),
('Civil drainage / public improvements','PE when KCC 12.10.060, the manual or director requires; simple compliant projects can have a nonengineered route. '+refs('07,60'),'Complete screening worksheet and simple plans where allowed; do not assume all drainage calculations are exempt.'),
('Boundary survey / plat','Licensed land surveyor for regulated survey work; fresh survey not universally mandatory for every permit. '+refs('18,04'),'Can draw a site plan from reliable accepted data; GIS is not a boundary survey.'),
('Wetland delineation / rating','Qualified wetland specialist where required; surveyed boundary when required by reviewer. '+refs('04'),'Owner observations help screening; credentials and accepted method govern a required report.'),
('Geotechnical / geology','Qualified professional report when triggered by site/code/reviewer. '+refs('03,05'),'Cannot substitute an owner soil description for a required professional report.'),
('Flood evidence','Professional certifications for specified floodproofing/V-zone/no-rise requirements; exact document qualification follows the code/form. '+refs('22'),'Owner submits; commissioning required technical evidence remains necessary.'),
('Archaeology','Qualified archaeologist for required investigations and permit application. '+refs('34,56'),'Owner supplies access and history; cannot replace professional investigation or government consultation.'),
('SEPA checklist / aquatic applications','No general requirement to hire a permit expediter; technical studies retain their qualification requirements. '+refs('23,36'),'Owner can coordinate and submit; cannot make the agency’s findings.'),
('Electrical work','Owner-work route exists; permit/inspection still applies. Hired electrical contractor purchases its permit. '+refs('49'),'Owner status does not cover hired unlicensed work.'),
('Special inspection / certification','Required where applicable. Kitsap added early identification through its Statement of Special Inspections requirement in 2026. '+refs('21'),'Budget and arrange the specified inspection; routine county inspections do not replace it.'),
('Project coordination','Recommended; no universal licensed “permit coordinator” requirement identified.','Owner may coordinate. The coordinator must not claim authority to approve regulated technical work.')])+'''<p><strong>Product field:</strong> store <code>credential_required</code>, <code>credential_type</code>, <code>scope</code>, <code>rule_basis</code>, <code>exception_path</code>, <code>agency_confirmation</code> and <code>verification_date</code>. “Professional recommended” must never be displayed as “legally required” without a basis.</p>''')
section('demo','09 · Interactive blocker explorer', '''<p>This is a <strong>synthetic demonstration</strong> of dependency behavior—not the status of a real parcel. Select a scenario, change a node’s state, and see which downstream milestones remain blocked. N/A here is only a simulation; a production system would require evidence. The model below intentionally uses a smaller subgraph than the full register.</p><div class="controls"><label>Scenario <select id="scenario"><option value="upland">Upland house / new septic</option><option value="shore">Shoreline house / aquatic work</option><option value="adu">ADU / existing septic</option></select></label><button id="reset">Reset example</button><button id="export">Export full node register (JSON)</button></div><div id="demoRows"></div><div id="result" aria-live="polite"></div><p class="muted">“Stale” withholds reliance on a changed input. “Conditional” remains blocked in this small demo because its simulated prestart conditions are unresolved. The full system should evaluate condition due-stage individually.</p>''')
section('examples','10 · Four practical paths and failure handling',table(['Project','Parallel work to start','Controlling sequence / likely bottleneck'],[
('Upland new house, new septic','Legal lot/access; septic soils; water supply; stormwater screening; house concept; environmental screening.','Resolve site interfaces → BSA/design approval → building release → septic installation authorization → inspections/final releases. Do not demand installed septic before issuing a building permit merely because the graph used one septic node. '+refs('12')),
('Existing house + ADU','Retrieve actual permitted OSS capacity and reserve; water evidence; local ADU land-use and building requirements; access/fire.','Existing system may qualify for clearance or may need a new BSA/upgrade. A prior functional septic system is not proof that added demand is approved. '+refs('13')),
('Shoreline bluff house, no work in water','Shoreline route; wetland/stream screen; geotechnical/drainage; septic/reserve; site alternatives.','Avoid automatically activating Corps/HPA solely because the parcel is waterfront. A new outfall, bulkhead or crossing can activate aquatic branches and change the critical path. '+refs('27,30')),
('Subdivision / larger commercial development','Use/plat path; whole-project SEPA; utilities and road capacity; geotechnical/environmental studies; coordinated civil design.','Land-use conditions → infrastructure permits / improvements or acceptable security → final plat/recording where applicable → individual building path. Stormwater common-plan scope can extend across phased lots; wastewater flow can change regulator. '+refs('02,37,48'))])+'''<h3>How to handle an agency rejection</h3><p>A failed technical review should create a bounded revision task, not simply restart the project. Example: the health reviewer finds the reserve field conflicts with the proposed stormwater feature. Freeze both conflicting features; have septic and civil compare compliant alternatives; check those alternatives against wetland geometry and building/access needs; obtain owner choice; update the common revision; revalidate only the affected assumptions internally. Submit wherever each agency requires—Bremerton’s published process explicitly describes all-department review after revisions. The software can target coordination effort even where agency resubmittal rules are broader. '''+refs('42')+'''</p><p>A substantive denial is different: record the rejected proposal and basis, then branch to redesign, an authorized exception/variance, appeal or abandonment. Never convert denial into a “pending task” that silently lets construction proceed.</p>''')
section('implementation','11 · Implementation specification for Davapprove', '''<p>The overall system is a <strong>directed graph with typed edges, milestone predicates and revision history</strong>. At one frozen revision the execution dependencies should usually be acyclic; design feedback creates cycles across successive revisions. Find strongly connected design components and manage them as coordinated work packages. A topological sort alone cannot decide applicability, property rights or professional judgment.</p>'''+table(['Object','Minimum fields'],[
('Project / scope','Parcel IDs, legal descriptions, jurisdiction/tenure, scope polygons, off-site work, units/bedrooms/use, disturbance/common plan, utilities, code editions, vesting evidence.'),
('Evidence','Document ID/hash, issuer/author, credentials, date, revision, surveyed/delineated geometry, method, limitations, accepted-by, expiration/revalidation rule, confidentiality.'),
('Decision','Agency, permit number, applicability basis, approved scope/revision, decision/effective/expiry dates, findings, conditions, appeals, modification history, source page.'),
('Edge','From/to, type, trigger expression, blocking milestone, legal source, exceptions, evidence dependencies, invalidation fields, confidence, human reviewer.'),
('Condition','Exact text, obligation, responsible party, due-stage, geographic scope, evidence needed, recurrence, release authority, status.'),
('Change event','Changed field/geometry, old/new revision, source, affected evidence/decisions, agency revalidation outcome, signer, timestamp.'),
('Work package','Location, activity/method, start/end window, requisite authorizations and rights, prestart evidence, explicit release decision.')])+'''<h3>Rules that prevent false green lights</h3><ol><li>Use three-valued applicability: true, false and unknown. Unknown cannot satisfy a construction release.</li><li>Distinguish “review can start,” “decision can issue,” “work can start” and “occupancy can occur.”</li><li>Evaluate AND gates over required branches; evaluate OR gates only over legally available alternatives.</li><li>Do not equate consultant completion, agency receipt, agency acceptance and permit effectiveness.</li><li>Propagate change only through declared dependent fields, but expand review when the dependency is uncertain.</li><li>Keep all approvals attached to their approved revision; do not overwrite the past with the current plan.</li><li>Show the smallest unresolved prerequisite sets blocking the chosen milestone, with a named next action and responsible party.</li><li>Maintain agency-specific review clocks and a separate owner-consultant clock. An agency’s public turnaround is not a deadline guarantee.</li><li>Attach authoritative text and source version to each rule. Preserve interpretation and reviewer confirmation separately.</li><li>Make the final work-release decision auditable and human-confirmed until validated against real permit files.</li></ol><h3>Recommended blocker display</h3><p><strong>“Grading cannot start:</strong> Ecology construction stormwater coverage pending; civil plan revision 7 has not been accepted under the site permit; the approved plan still shows the former drainage route. <strong>Can continue:</strong> unrelated interior design and structural detailing that do not depend on the moved foundation. <strong>Next actions:</strong> civil engineer resolves discharge route; coordinator obtains environmental scope check; applicant submits coordinated revision.” This is a proposed display example, not an actual agency finding.</p><h3>Useful measurements</h3><p>Track inter-discipline conflicts found before submittal; revision rounds caused by mismatched plans; days waiting on owner, consultant and agency separately; time from parcel intake to a defensible coordinated envelope; number of formerly accepted decisions requiring amendment; and unresolved assumptions at detailed-design release. Measure these on real projects before claiming cost or approval-time savings.</p>''')
section('limits','12 · Validation boundaries and next verification work', '''<p>This is a substantial reference graph, but the distinction between a workflow map and an executable legal ruleset matters. The sources establish the major authorities and dependency patterns. They do not establish a universally applicable numeric buffer, permit threshold, appeal deadline or mandatory submission sequence for every Kitsap parcel.</p>'''+table(['Issue','What is established here','What must be confirmed for implementation'],[
('Cities','Separate city permitting paths and department routing.','Each city’s current CAO/SMP, drainage thresholds, design review, tree code, fire authority arrangements and application-specific dependencies.'),
('Tribal / federal lands','Land tenure changes routing; tribes have sovereign, treaty and cultural roles.','Parcel-specific authority, trust/lease approvals, relevant tribes and competent 401/NPDES authority; do not generalize Port Madison FAQ to every reservation.'),
('Owner septic design','State discretionary exception exists; local ordinance requires licensed design.','Any claimed Kitsap exception requires written health-officer/legal basis before use.'),
('Structural calculations','Architect exemptions are not a general engineering exemption; prescriptive and engineered paths differ.','Current adopted code and official requirements for the actual structural system. Historical 2007 brochure used only for the distinction.'),
('Wetland / shoreline dimensions','Qualified studies and several overlapping regulatory routes exist.','Actual classification, designation, buffers, setbacks, authorized reductions, method version and field/agency acceptance.'),
('Code transitions and old reports','Old approvals and reports remain useful evidence, not automatic present authorization.','Vesting by permit, new enactments not yet codified, expiration, changed site conditions and professional revalidation. Do not impose a universal five-year expiration on all reports.'),
('Special projects','Screen branches for larger wastewater, forest conversion, flood, archaeology, electrical, aquatic work and federal property.','Air quality/asbestos/demolition, contaminated-site cleanup, public-water-system expansion, specialized industrial discharge, bridges/navigation, dam safety, airport overlays, and sector-specific permits need additional modules.'),
('Permitting exemptions','An exemption applies to a specified permit or review.','Verify other laws/approvals still applicable; never interpret a single exemption as complete project clearance.')])+'''<p><strong>Priority validation cases:</strong> replay one new rural septic house, one existing-system ADU, one shoreline/bluff project, one wetland-constrained site, and one city subdivision. Compare the graph against actual agency notices, correction rounds, approved revisions and final conditions. Resolve discrepancies with the relevant reviewer and preserve the explanation as jurisdiction-specific evidence.</p><p><strong>Source handling:</strong> current codified code and enacted amendments take priority over handouts. Agency web pages can themselves retain obsolete material. This report deliberately avoids encoding historical buffer numbers or 2007 engineering dimensions. Source links below support the specific nearby claims, not every possible rule in the linked chapter.</p>''')
section('sources','13 · Source register', '<p>Primary agency, statutory and officially hosted code references. Accessed November 5, 2026. References are clickable throughout the report.</p><ol class="sources">'+''.join(f'<li id="s{k}"><b>[{k}]</b> <a href="{html.escape(v[1])}" target="_blank" rel="noopener">{html.escape(v[0])}</a></li>' for k,v in S.items())+'</ol>')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#20333e;background:#f4f6f5;font:16px/1.6 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{background:#123443;color:white;padding:54px max(24px,calc((100vw - 1120px)/2));border-bottom:7px solid #52b3a5}h1{font-size:42px;line-height:1.14;max-width:850px;margin:14px 0}header p{max-width:850px;color:#d4e4e8}header .eyebrow{font-size:13px;letter-spacing:.16em;font-weight:700}main{max-width:1168px;margin:auto;padding:24px}nav{display:flex;flex-wrap:wrap;gap:9px 20px;padding:20px 0 28px}nav a{font-weight:650;font-size:14px}a{color:#08796f;text-underline-offset:3px}section{background:white;padding:30px 34px;margin:0 0 24px;border:1px solid #dce5e5;border-radius:8px;scroll-margin-top:20px}h2{font-size:25px;line-height:1.25;margin:0 0 22px;color:#123443}h3{font-size:19px;margin-top:30px}p{margin:14px 0}.lead{font-size:20px;line-height:1.55}.muted{color:#5d7179}.ref{font-size:12px;white-space:nowrap}.tablewrap{overflow-x:auto;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.5}th{text-align:left;background:#eaf2f3;color:#193e4b;font-weight:700}th,td{padding:13px 12px;border-bottom:1px solid #dbe3e5;vertical-align:top}td:first-child{min-width:140px}tr:nth-child(even) td{background:#f8faf9}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf4f4;padding:22px;font-size:13px;line-height:1.7}code{overflow-wrap:anywhere}.graph{margin:22px auto;max-width:100%;overflow:auto;text-align:center}.graph svg{width:auto;max-width:100%;height:auto;max-height:900px}.sources{padding:0;list-style:none;columns:2;column-gap:32px}.sources li{font-size:13px;padding:7px 0;break-inside:avoid;overflow-wrap:anywhere}.controls{display:flex;gap:14px;align-items:end;flex-wrap:wrap}label{display:grid;gap:5px;font-size:14px;font-weight:650}select,button{font:inherit;border:1px solid #a5b8bd;background:white;border-radius:5px;padding:9px 12px;color:#173d47}button{cursor:pointer}button:hover{background:#e3f2ed}.status{font-weight:700}.ok{color:#08764d}.blocked{color:#a43e26}#result{border-left:4px solid #38998d;background:#edf6f3;padding:16px 20px}.demoselect{max-width:190px;width:100%}footer{text-align:center;color:#60737b;padding:20px;font-size:13px}@media(max-width:650px){h1{font-size:31px}header{padding:32px 22px}main{padding:12px}section{padding:24px 17px}h2{font-size:22px}.sources{columns:1}.graph svg{min-width:570px}.lead{font-size:18px}th,td{padding:10px;font-size:13px}}@media print{body{background:white;font-size:10pt}header{background:white;color:#123443;padding:20px 0;border-bottom:3px solid #52b3a5}header p{color:#384e57}h1{font-size:30pt}main{max-width:none;padding:0}section{border:0;padding:18px 0;margin:0;break-before:page}nav,.controls,#demoRows,#result{display:none}.graph svg{max-height:650px}table{font-size:9pt}tr{break-inside:avoid}thead{display:table-header-group}h2,h3{break-after:avoid}.sources{columns:2}a{color:inherit}.tablewrap{overflow:visible}pre{font-size:9pt}}'''
js=r'''
const scenarios={
upland:{names:{base:'Shared site evidence',water:'Water adequacy',septic:'Septic design / BSA',civil:'Civil / drainage review',local:'Local building reviews',issue:'Building issuance',install:'Septic installation permit',start:'Release septic construction'},deps:{base:[],water:[],septic:['base','water'],civil:['base'],local:['base','civil'],issue:['water','septic','local'],install:['issue','septic'],start:['install']},initial:{base:'accepted',water:'accepted',septic:'reviewing',civil:'accepted',local:'accepted',issue:'ready',install:'ready',start:'ready'}},
shore:{names:{base:'Shared shoreline design',local:'Local shoreline decision',eco:'Ecology CUP / variance',wait:'Shoreline waiting/review period',cert:'401 certification',consult:'Federal consultations',corps:'Corps authorization',hpa:'WDFW HPA',rights:'Aquatic property authorization',start:'Release aquatic construction'},deps:{base:[],local:['base'],eco:['local'],wait:['eco'],cert:['base'],consult:['base'],corps:['cert','consult'],hpa:['base'],rights:[],start:['wait','corps','hpa','rights']},initial:{base:'accepted',local:'accepted',eco:'accepted',wait:'waiting',cert:'accepted',consult:'reviewing',corps:'ready',hpa:'accepted',rights:'accepted',start:'ready'}},
adu:{names:{scope:'Bedroom / use scope',water:'Water adequacy',septic:'Existing-system clearance',site:'Site interfaces',building:'Building reviews',issue:'Building issuance'},deps:{scope:[],water:[],septic:['scope','water'],site:['scope'],building:['site'],issue:['septic','water','building']},initial:{scope:'accepted',water:'accepted',septic:'stale',site:'accepted',building:'accepted',issue:'ready'}}};
let config, states;
function evaluate(id,stack=[]){if(stack.includes(id))throw Error('Cycle');if(states[id]==='na')return {ok:true,why:[]};let deps=config.deps[id].flatMap(d=>{let r=evaluate(d,[...stack,id]);return r.ok?[]:r.why});let own=['accepted','ready'].includes(states[id])?[]:[id];let why=[...new Set([...deps,...own])];return {ok:!why.length,why};}
function render(){document.getElementById('demoRows').innerHTML='<div class="tablewrap"><table><thead><tr><th>Node</th><th>Simulated state</th><th>Dependency result</th></tr></thead><tbody>'+Object.keys(config.names).map(id=>{let r=evaluate(id);return '<tr><td>'+config.names[id]+'</td><td><select class="demoselect" aria-label="State for '+config.names[id]+'" data-node="'+id+'">'+[['accepted','Accepted / effective'],['ready','Ready after prerequisites'],['unknown','Unknown'],['reviewing','Under review'],['waiting','Waiting period'],['conditional','Conditions unresolved'],['denied','Denied'],['stale','Stale / changed'],['expired','Expired'],['na','N/A (demo only)']].map(([v,t])=>'<option value="'+v+'" '+(states[id]===v?'selected':'')+'>'+t+'</option>').join('')+'</select></td><td class="status '+(r.ok?'ok':'blocked')+'">'+(r.ok?'Pass':'Blocked: '+r.why.map(x=>config.names[x]).join('; '))+'</td></tr>'}).join('')+'</tbody></table></div>';document.querySelectorAll('[data-node]').forEach(el=>el.onchange=()=>{states[el.dataset.node]=el.value;render()});const target=Object.keys(config.names).at(-1),r=evaluate(target);document.getElementById('result').innerHTML='<strong>'+config.names[target]+': '+(r.ok?'prerequisites pass in this simulation':'blocked')+'</strong><p>'+(r.ok?'A real release still requires verified agency evidence and a responsible release decision.':'Resolve: '+r.why.map(x=>config.names[x]+' ('+states[x]+')').join('; ')+'.')+'</p>';}
function reset(){config=scenarios[document.getElementById('scenario').value];states={...config.initial};render()}document.getElementById('scenario').onchange=reset;document.getElementById('reset').onclick=reset;document.getElementById('export').onclick=()=>{let b=new Blob([document.getElementById('registry').textContent],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='Davapprove_Kitsap_Node_Register.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};reset();
'''
nav=[('read','System'),('jurisdiction','Jurisdiction'),('design','Design loop'),('nodes','Node register'),('external','External gates'),('edges','Dependencies'),('states','States & revisions'),('professionals','Owner / professional'),('demo','Blocker explorer'),('implementation','Implementation'),('sources','Sources')]
registry={'title':'Davapprove Kitsap approval dependency node register','as_of':'2026-11-05','scope':'Research reference, not parcel-specific authorization','nodes':N,'sources':S}
out='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Davapprove | Kitsap Approval Dependency Graph</title><style>'+css+'</style></head><body><header><div class="eyebrow">DAVAPPROVE · RESEARCH & WORKFLOW SPECIFICATION</div><h1>Kitsap development approval dependency graph</h1><p>Inter-agency approvals. Inter-discipline design. Explicit blockers, change propagation and professional requirements.</p><p>November 5, 2026 · '+str(len(N))+' node templates · 4 graph views · 3 interactive examples · '+str(len(S))+' primary references</p></header><main><nav>'+''.join(f'<a href="#{i}">{t}</a>' for i,t in nav)+'</nav>'+''.join(parts)+'</main><footer>Davapprove · Model rules and recommendations are distinguished from agency requirements.</footer><script id="registry" type="application/json">'+json.dumps(registry,ensure_ascii=False).replace('</', r'<\/')+'</script><script>'+js+'</script></body></html>'
(P/'Davapprove_Kitsap_Approval_Dependency_Graph.html').write_text(out, encoding='utf-8')
(P/'kitsap-node-register.json').write_text(json.dumps(registry, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'file':str(P/'Davapprove_Kitsap_Approval_Dependency_Graph.html'),'nodes':len(N),'sources':len(S),'bytes':len(out.encode())}))
